(431,220,$mw$10CE3D191495EDB2E300A6AE9DC264DE789EC6135754669B9B26A22B299C232C$mw$,$mw$fea0abfdf088e6989c743c722fda5bc0$mw$,$mw$$mw$,$mw${"Id":220,"StageId":2,"CategoryId":34,"Points":10,"TitleAr":"مثلثان متشابهان. طول ضلع في الأول 3 ومعامل التكبير 2، ما طول الضلع المناظر؟","TitleEn":"Similar triangles: a side is 3 with scale factor 2. Find the corresponding side.","QuestionTextAr":"مثلثان متشابهان. طول ضلع في الأول 3 ومعامل التكبير 2، ما طول الضلع المناظر؟","QuestionTextEn":"Similar triangles: a side is 3 with scale factor 2. Find the corresponding side.","DetailedSolutionAr":"المبدأ المستخدم: في المثلثات المتشابهة تتناسب الأضلاع المتناظرة بعامل التشابه نفسه. إذا كان الضلع الأصلي 3 وعامل التكبير 2، فالضلع المناظر = 3 × 2 = 6. نضرب الأطوال في العامل، ولا نربعه إلا عند حساب المساحات.","DetailedSolutionEn":"Rule used: Corresponding side lengths of similar triangles are multiplied by the linear scale factor. An original side of 3 with scale factor 2 gives corresponding side = 3 × 2 = 6. Square the scale factor for areas, not for side lengths.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":869,"Order":1,"LatexCode":"4","IsCorrect":false},{"Id":870,"Order":2,"LatexCode":"6","IsCorrect":true},{"Id":871,"Order":3,"LatexCode":"7","IsCorrect":false},{"Id":872,"Order":4,"LatexCode":"9","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"حدد اتجاه التكبير من A إلى B.","En":"Identify the enlargement direction from A to B."},{"Ar":"اضرب طول الضلع في معامل تكبير الأطوال.","En":"Multiply the side length by the length scale factor."}],"Title":{"Ar":"طول ضلع مناظر في مثلث مكبّر","En":"Corresponding side in an enlarged triangle"},"Points":10,"Options":[{"Reason":{"Ar":"النسبة $4/3$ لا تساوي معامل التكبير 2.","En":"The ratio $4/3$ is not the scale factor 2."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"4"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"6"},{"Reason":{"Ar":"النسبة $7/3$ لا تساوي معامل التكبير 2.","En":"The ratio $7/3$ is not the scale factor 2."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"7"},{"Reason":{"Ar":"النسبة $9/3$ لا تساوي معامل التكبير 2.","En":"The ratio $9/3$ is not the scale factor 2."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"9"}],"StageId":2,"Question":{"Ar":"مثلثان متشابهان A وB. طول أحد أضلاع المثلث A يساوي 3 وحدات طول، ومعامل التكبير من A إلى B يساوي 2. ما طول الضلع المناظر في B؟","En":"Triangles A and B are similar. A side of triangle A has length 3 units, and the length scale factor from A to B is 2. What is the corresponding side length in B?"},"Solution":{"Idea":{"Ar":"أطوال الأضلاع المتناظرة في الأشكال المتشابهة تتناسب مع معامل التشابه.","En":"Corresponding lengths in similar figures scale by the similarity factor."},"Unit":{"Ar":"وحدة طول","En":"Length units"},"Steps":[{"Ar":"$l_A=3,\\quad k=2$","En":"$l_A=3,\\quad k=2$"},{"Ar":"$l_B=k l_A=2\\cdot3=6$","En":"$l_B=k l_A=2\\cdot3=6$"}],"Result":{"Ar":"$6$","En":"$6$"},"CommonError":{"Ar":"معامل الطول يختلف عن معامل المساحة المربع.","En":"The length scale factor is not its square, which scales areas."},"FormulaLatex":"l_2=kl_1","Substitution":{"Ar":"$2\\cdot3=6$","En":"$2\\cdot3=6$"},"Verification":{"Ar":"$6/3=2$","En":"$6/3=2$"}},"TrackIds":[8],"CategoryId":34,"PrimarySkillId":40,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"حدد اتجاه التكبير من A إلى B.","En":"Identify the enlargement direction from A to B."},{"Ar":"اضرب طول الضلع في معامل تكبير الأطوال.","En":"Multiply the side length by the length scale factor."}],"Solution":{"Idea":{"Ar":"أطوال الأضلاع المتناظرة في الأشكال المتشابهة تتناسب مع معامل التشابه.","En":"Corresponding lengths in similar figures scale by the similarity factor."},"Unit":{"Ar":"وحدة طول","En":"Length units"},"Steps":[{"Ar":"$l_A=3,\\quad k=2$","En":"$l_A=3,\\quad k=2$"},{"Ar":"$l_B=k l_A=2\\cdot3=6$","En":"$l_B=k l_A=2\\cdot3=6$"}],"Result":{"Ar":"$6$","En":"$6$"},"CommonError":{"Ar":"معامل الطول يختلف عن معامل المساحة المربع.","En":"The length scale factor is not its square, which scales areas."},"FormulaLatex":"l_2=kl_1","Substitution":{"Ar":"$2\\cdot3=6$","En":"$2\\cdot3=6$"},"Verification":{"Ar":"$6/3=2$","En":"$6/3=2$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"النسبة $4/3$ لا تساوي معامل التكبير 2.","En":"The ratio $4/3$ is not the scale factor 2."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"النسبة $7/3$ لا تساوي معامل التكبير 2.","En":"The ratio $7/3$ is not the scale factor 2."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"النسبة $9/3$ لا تساوي معامل التكبير 2.","En":"The ratio $9/3$ is not the scale factor 2."},"Order":4}]}$mw$,$mw$أطوال الأضلاع المتناظرة في الأشكال المتشابهة تتناسب مع معامل التشابه.

